import {aigcLocations} from '../reports/report-locations.mjs';
import {aigcParagraphReview} from '../reports/aigc-review.mjs';
import {AIGC_PARAGRAPH_VERSION} from '../reports/aigc-partitions.mjs';
import {reportDocument,reportDate,reportEscape as escape} from '../reports/report-document.mjs';
import {AIGC_NOTICE,aigcLabel,normalizeAigcResult,aigcLabelCoverage} from './aigc-detection-model.mjs';
const format=value=>Number(value).toLocaleString('en-US');
const tag=label=>label==='aigc'?'risk':label==='ugc'?'human':'unknown';
const score=value=>value===null?'—':`${Number(value.toFixed(2))} / 100`;
const metric=(label,value)=>`<div class="report-metric"><strong>${escape(value)}</strong><small>${escape(label)}</small></div>`;
export function aigcReportHtml(value,{text='',title=value?.title||'本次送检论文',demo=false}={}){
 const item=normalizeAigcResult(value);
 if(!item.fullyCompleted)throw Error('本次鉴别尚未完整结束，不能导出完成报告。');
 let offset=0;
 const valid=item.parts.every((part,index)=>{const ok=part.index===index&&part.start===offset&&part.end>part.start&&part.end<=item.characters&&part.characters===part.end-part.start;offset=part.end;return ok;})&&offset===item.characters;
 if(!valid)throw Error('分段位置与鉴别字符数无法核对，暂不能导出报告。');
 const size=Array.from(typeof text==='string'?text:'').length;if(size&&size!==item.characters)throw Error('本次原文与鉴别字符数不一致，不能附加到报告。');
 const hasText=size===item.characters,coverage=aigcLabelCoverage(item),modern=item.analysisVersion===AIGC_PARAGRAPH_VERSION,locations=hasText?aigcLocations(text,item.parts):{visible:[],total:0};
 const summary=`<section class="report-panel" id="report-summary"><h2 class="report-section-title">一  检测结果总览</h2><p class="report-verdict">${escape(aigcLabel(item.verdict))}</p><div class="report-metrics">${metric('疑似 AI 片段字符占比',coverage.available?(coverage.ratio*100).toFixed(1)+'%':'暂不能计算')}${metric('疑似 AI 片段字符数',coverage.available?format(coverage.aiCharacters):'未形成有效统计')}${metric('有效检测字符',coverage.available?format(coverage.testedCharacters):'未形成有效统计')}${metric('本次送检字符',format(item.characters))}</div><p class="report-muted">疑似范围与判断置信分分别展示，置信分不可平均或换算成 AI 率。存在无法明确判定的内容时，不给出整篇占比。</p></section>`;
 const findings=`<section class="report-panel" id="report-findings"><h2 class="report-section-title">二  疑似原文定位</h2>${!hasText?'<p>本条历史记录缺少送检原文，不能提供原文定位。</p>':locations.total?`<p>本次标记范围涉及 ${locations.total} 段原文。点击定位，查看该段正文与右侧分析。</p>${!modern?'<p class="report-muted">历史结果保留原检测范围，不表示其中每一句话都单独判为 AI 生成。</p>':''}<table class="report-table report-findings-table"><thead><tr><th>原文位置</th><th>论文原文摘录</th><th>核对入口</th></tr></thead><tbody>${locations.visible.map(row=>`<tr><td>原文第 ${row.number} 段</td><td><p class="report-text">${escape(row.excerpt)}</p></td><td><a href="#${row.target}">定位原文 ↓</a><br><a href="#ai-analysis-${row.number}">查看段落分析 ↓</a></td></tr>`).join('')}</tbody></table>${locations.total>locations.visible.length?'<p class="report-muted">定位列表展示前300段；下方对照仍保留全部送检文字和实际检测结果。</p>':''}`:'<p>本次未标记疑似 AI 范围；请在下方逐段核对原文与分析。</p>'}</section>`;
 const review=hasText?`<section class="report-panel report-page-break" id="report-text"><h2 class="report-section-title">三  正文与逐句修改建议</h2><p class="report-muted">左侧保留送检正文，疑似范围标红；右侧展示段落检测结果，并逐句给出原句、修改点及可用的参考改写。逐句修改建议用于文字编辑，不代表逐句 AI 作者判定；不会更改本次送检原文。${modern?'按自然段对应分析，不作逐句判定。':'历史记录保留原检测范围，不把范围结果作为每段的独立结论；不作逐句判定。'}</p><table class="report-review-table" aria-label="论文正文与逐句修改建议"><colgroup><col style="width:55%"><col style="width:45%"></colgroup><thead><tr><th>论文正文 · 疑似内容标注</th><th>修改建议 · 逐句对应正文</th></tr></thead><tbody>${aigcParagraphReview(text,item)}</tbody></table></section>`:'<section class="report-panel" id="report-text"><h2 class="report-section-title">三  原文核对说明</h2><p>当前历史记录不保存正文，报告只包含已有结果，不附加其他版本的文本。</p></section>';
 const rows=item.parts.map((part,index)=>`<tr><td>${part.paragraphNumber?'第 '+part.paragraphNumber+' 段':index+1}</td><td>${format(part.start+1)}–${format(part.end)}</td><td>${format(part.effectiveCharacters??part.characters)}</td><td><span class="report-tag-${tag(part.label)}">${escape(part.skipped?(part.skipReason==='non_text'?'非正文内容，未参与判断':'空白分段，已跳过'):aigcLabel(part.label))}</span></td><td>${score(part.confidence)}</td></tr>`).join('');
 const body=`${findings}${review}<section class="report-panel" id="report-parts"><h2 class="report-section-title">四  检测明细</h2><table class="report-table"><thead><tr><th>原文位置</th><th>字符位置</th><th>检测字符</th><th>表达倾向</th><th>判断置信分</th></tr></thead><tbody>${rows}</tbody></table></section><section class="report-panel" id="report-method"><h2 class="report-section-title">五  检测说明</h2><p>疑似 AI 表达与偏人工表达均为本次文本的检测结果，不能证明作者身份或具体生成过程。无法明确判断的内容不会默认计入人工表达。</p><p>请结合研究过程、数据材料、引用来源和修改记录核对。结果对应本次送检版本，修改后的正文需要重新检测。</p></section>`;
 return reportDocument({title,type:'论文 AI 率检测报告',id:item.id,createdAt:item.createdAt,scope:modern?'本次提交文本的逐段 AI 表达检测':'本次提交文本的原检测范围',navigation:[['report-summary','检测总览'],['report-findings','疑似原文定位'],['report-text','正文与逐句修改建议'],['report-parts','检测明细'],['report-method','检测说明']],metadata:[['完成时间',reportDate(item.updatedAt)],['原文呈现',hasText?'本次送检正文与对应分析':'历史摘要；未附原文'],['报告状态','检测完成']],summary,body,notice:AIGC_NOTICE,demo});
}
